// Generates TypeScript types for the backend API from its OpenAPI document.
//
//   npm run api:types    regenerate from the committed api/openapi.json
//   npm run api:update   fetch the spec from a running API first, then regenerate
//
// api:update reads API_SPEC_URL (default: the backend's local dev address).
// Commit api/openapi.json and the generated file together; CI fails when the
// generated file does not match the committed spec.

import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const SPEC_PATH = new URL("../api/openapi.json", import.meta.url);
const OUT_PATH = new URL("../src/lib/api-schema.gen.ts", import.meta.url);
const DEFAULT_SPEC_URL = "http://localhost:5294/openapi/v1.json";

/**
 * Properties the backend sends as an enum's name (`Enum.ToString()`) but
 * declares as a plain string, so the spec cannot list the values. These lists
 * copy the backend's enums in ClinicManagement.Domain/Enums; update them
 * together.
 */
const APPOINTMENT_STATUS = [
  "REQUESTED",
  "CONFIRMED",
  "DECLINED",
  "CANCELLED",
  "COMPLETED",
];
const VERIFICATION_STATUS = ["PENDING", "VERIFIED", "REJECTED"];
const GENDER = ["MALE", "FEMALE", "OTHER"];
const STRING_ENUMS = {
  "AppointmentListResponse.status": APPOINTMENT_STATUS,
  "AppointmentResponse.status": APPOINTMENT_STATUS,
  // Only decided requests: the backend's query filters to these two.
  "PatientRecentDecision.status": ["CONFIRMED", "DECLINED"],
  "PatientVisitResponse.status": APPOINTMENT_STATUS,
  "ProviderResponse.verificationStatus": VERIFICATION_STATUS,
  "MeLinkedProvider.verificationStatus": VERIFICATION_STATUS,
  "ProviderResponse.gender": GENDER,
};

if (process.argv.includes("--fetch")) {
  const url = process.env.API_SPEC_URL || DEFAULT_SPEC_URL;
  const response = await fetch(url).catch((error) => {
    throw new Error(
      `Could not reach ${url}. Start the backend in Development, or set API_SPEC_URL. (${error.message})`,
    );
  });
  if (!response.ok) throw new Error(`GET ${url} returned ${response.status}`);
  const spec = await response.json();
  await writeFile(SPEC_PATH, `${JSON.stringify(spec, null, 2)}\n`);
  console.log(`Saved spec from ${url}`);
}

const spec = JSON.parse(await readFile(SPEC_PATH, "utf8"));
normalizeNumbers(spec);
applyStringEnums(spec);

const ast = await openapiTS(spec, {
  // Absent optional properties stay `prop?: T`, not `prop?: T | undefined`.
  exactOptionalPropertyTypes: false,
  // Nullable properties the backend always sends stay required.
  defaultNonNullable: true,
});

const header = `// Generated by scripts/generate-api-types.mjs from api/openapi.json.
// Do not edit by hand: run \`npm run api:types\` (or \`npm run api:update\`).
/* biome-ignore-all lint: generated file */

`;
await writeFile(OUT_PATH, header + astToString(ast));
console.log("Wrote src/lib/api-schema.gen.ts");

/** Adds the allowed values to the properties in STRING_ENUMS. */
function applyStringEnums(spec) {
  for (const [path, values] of Object.entries(STRING_ENUMS)) {
    const [schemaName, property] = path.split(".");
    const schema =
      spec.components?.schemas?.[schemaName]?.properties?.[property];
    if (!schema)
      throw new Error(
        `${path} is not in the spec any more; update STRING_ENUMS in scripts/generate-api-types.mjs.`,
      );
    const nullable = Array.isArray(schema.type) && schema.type.includes("null");
    schema.enum = nullable ? [...values, null] : values;
  }
}

/**
 * .NET writes numbers as numbers but describes them as `integer | string`
 * (it would also accept strings on input). The frontend only reads what the
 * API writes, so keep the number type and drop the string alternative.
 */
function normalizeNumbers(node) {
  if (Array.isArray(node)) {
    for (const item of node) normalizeNumbers(item);
    return;
  }
  if (!node || typeof node !== "object") return;
  if (Array.isArray(node.type)) {
    const numeric = node.type.find((t) => t === "integer" || t === "number");
    if (numeric && node.type.includes("string")) {
      const rest = node.type.filter((t) => t !== "string");
      node.type = rest.length === 1 ? rest[0] : rest;
      delete node.pattern;
    }
  }
  for (const value of Object.values(node)) normalizeNumbers(value);
}
